(() => {
  'use strict';
  const D=window.SAMT_DATA,C=window.SAMT_CORE,$=s=>document.querySelector(s);
  const STORE='samt6-demo-v1'; let lang='ar',state=C.seed(),storageOK=true,activeFellow='D-001',lastFocus=null;
  try {lang=localStorage.getItem('samt6-language')==='en'?'en':'ar';const raw=localStorage.getItem(STORE);if(raw){const parsed=JSON.parse(raw);if(C.validState(parsed))state=parsed;}}catch{storageOK=false;}
  const b=(ar,en)=>lang==='ar'?ar:en, tr=x=>typeof x==='object'?x[lang]:x;
  const esc=x=>String(x??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
  const num=n=>new Intl.NumberFormat(lang==='ar'?'ar-AE':'en-GB',{maximumFractionDigits:0}).format(n);
  const unit=b('د.إ','AED');
  const route=()=>location.hash.slice(1).split('/').filter(Boolean);
  const label={
    nominated:['مرشّح','Nominated'],eligible:['مستوفٍ للأهلية','Eligible'],assessing:['قيد التقييم','In assessment'],panel:['مراجعة اللجنة','Panel review'],selected:['مختار','Selected'],waitlist:['قائمة الاحتياط','Reserve list'],rejected:['غير مختار','Not selected'],
    military:['عسكري','Military'],civilian:['مدني','Civilian'],early:['بداية المسار','Early career'],mid:['منتصف المسار','Mid career'],
    operations:['العمليات','Operations'],capability:['تطوير القدرات','Capability development'],people:['الموارد البشرية','People'],finance:['المالية','Finance'],logistics:['الإمداد والدعم','Logistics and support'],technology:['التقنية والابتكار','Technology and innovation'],
    planned:['مخطط','Planned'],progress:['قيد التطبيق','In progress'],validated:['مراجعة منفعة مكتملة','Benefit review complete'],
    seed:['تحميل بيانات العرض','Demo data loaded'],nomination:['إضافة ترشيح افتراضي','Sample nomination added'],decision:['تسجيل قرار لجنة','Panel decision recorded'],capacity:['تعديل حجم الدفعة','Cohort capacity updated'],learning:['حفظ دليل تعلم','Learning evidence saved'],assessment:['تحديث تقييم','Assessment updated'],monitoring:['تحديث المتابعة','Follow-up updated']
  };
  const lab=k=>label[k]?b(...label[k]):k;
  const stageBadge=s=>`<span class="badge ${esc(s)}">${lab(s)}</span>`;
  const link=(hash,text,cls='btn')=>`<a class="${cls}" href="#${hash}">${text}<span aria-hidden="true">${lang==='ar'?'←':'→'}</span></a>`;
  const errorText=code=>({invalid_transition:b('لا يمكن الانتقال مباشرة إلى هذه المرحلة.','This stage cannot be reached directly.'),reason_required:b('اكتب سبباً للقرار من 8 أحرف على الأقل.','Enter a decision reason of at least 8 characters.'),eligibility_required:b('يجب استيفاء شروط الأهلية الثلاثة أولاً.','All three eligibility conditions must be met first.'),second_assessor:b('أكد اكتمال مراجعة المقيم الثاني قبل إقرار هذه المرحلة.','Confirm a second assessor’s review before approving this stage.'),capacity_full:b('اكتملت سعة الدفعة. يمكن استخدام قائمة الاحتياط.','The cohort is full. Use the reserve list.'),invalid_capacity:b('الحجم بين 1 و20 ولا يمكن أن يقل عن عدد المختارين.','Capacity must be 1–20 and cannot be below the selected count.'),mod_required:b('المبادرة مخصصة لمنتسبي وزارة الدفاع.','SAMT is for MOD personnel.'),evidence_required:b('أضف دليلاً أو ملاحظة من 12 حرفاً على الأقل.','Add evidence or a note of at least 12 characters.'),invalid_scores:b('التقييم يجب أن يكون بين 1 و5.','Ratings must be between 1 and 5.'),invalid_budget:b('تحقق من المدخلات: الدفعة حتى 20، والقيم غير سالبة، والاحتياطي حتى 100%.','Check inputs: cohort up to 20, non-negative values, contingency up to 100%.')})[code]||b('تعذر حفظ التغيير. تحقق من البيانات.','The change could not be saved. Check the values.');
  function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{storageOK=false;toast(b('تم التغيير في هذه الجلسة فقط؛ الحفظ المحلي غير متاح.','Changed for this session only; browser storage is unavailable.'));}}
  function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4500);}
  function closeModal(){if($('#modal').open)$('#modal').close();lastFocus?.focus();}
  function modal(title,body){lastFocus=document.activeElement;$('#modal').innerHTML=`<div class="dialog-inner"><div class="dialog-top"><h2 id="dialog-title">${title}</h2><button class="close" data-close aria-label="${b('إغلاق','Close')}">×</button></div>${body}</div>`;$('#modal').setAttribute('aria-labelledby','dialog-title');$('#modal').showModal();}
  function header(page){return `<header class="header"><div class="shell"><a class="brand" href="#home" aria-label="${b('سَمْت — الرئيسية','SAMT — Home')}"><img src="assets/mark.svg" width="40" height="40" alt=""><span><span class="brand-word" lang="ar">سَمْت</span><small>SAMT</small></span></a><nav class="nav" id="navigation" aria-label="${b('التنقل الرئيسي','Main navigation')}">${D.nav.map(([id,title])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${tr(title)}</a>`).join('')}</nav><div class="header-tools"><button class="lang" data-action="language" aria-label="${b('Switch to English','التبديل إلى العربية')}">${b('EN','عربي')}</button><button class="menu-button" data-action="menu" aria-controls="navigation" aria-expanded="false" aria-label="${b('القائمة','Menu')}">☰</button></div></div></header>`;}
  function footer(){return `<footer class="footer"><div class="shell"><p><strong>${b('سَمْت — مبادرة مقترحة لإعداد القيادات','SAMT — A proposed leadership-development initiative')}</strong><br>${b('مقترح مقدم للعرض على وزارة الدفاع. الجهات المضيفة مقترحة، والترتيبات خاضعة للموافقة والاتفاق الرسمي. بيانات المنصة افتراضية.','A proposal for MOD consideration. Hosts are proposed and arrangements require formal approval and agreement. Platform data is fictional.')}</p><a href="https://github.com/AhmedYYYA/samt6" target="_blank" rel="noopener">SAMT6 · GitHub ↗</a></div></footer>`;}
  function home(){return `<main id="main" tabindex="-1"><div class="shell"><section class="hero"><div><span class="tag">${b('مبادرة لإعداد قيادات وزارة الدفاع','A leadership initiative for the Ministry of Defence')}</span><h1>${b('فهمٌ أوسع.<br><span>قيادةٌ أبعد أثراً.</span>','A wider perspective.<br><span>A greater capacity to lead.</span>')}</h1><p class="lead">${b('نصل خبرة الأجيال بإمكانات المواهب الاستثنائية. رحلة متكاملة تصقل الحكم القيادي وتمنح العسكريين والمدنيين فهماً عميقاً للمنظومة التي سيقودونها.','Connecting the experience of one generation with the potential of the next. An integrated journey developing leadership judgement and a deep understanding of the institution military and civilian talent will help lead.')}</p><div class="actions">${link('proposal',b('استعرض ملف الاعتماد','Explore the approval case'))}${link('demo',b('جرّب المنصة','Try the platform'),'btn secondary')}</div><p class="hero-note">${b('مبادرة شخصية تسعى إلى تبنّي وزارة الدفاع واعتمادها. العرض الحالي يستخدم بيانات افتراضية.','A personal initiative seeking MOD endorsement and adoption. The current demonstration uses fictional data.')}</p></div><div class="journey-art" aria-label="${b('مسار البرنامج في أربع دول خلال 16 أسبوعاً','Programme route across four countries in 16 weeks')}"><div class="art-top"><span>SAMT / THE LEADERSHIP JOURNEY</span><span>01—16</span></div><div class="art-number"><b>16</b><div>${b('أسبوعاً متتالياً<br>بدوام كامل','consecutive weeks<br>full time')}</div></div><div class="art-route">${D.stations.map((s,i)=>`<a href="#programme/${s.id}" class="art-stop"><small>0${i+1}</small><span class="stop-name">${tr(s.country)}</span><span class="stop-weeks">${num(s.weeks)} ${b('أسابيع','weeks')}</span></a>`).join('')}</div><div class="art-footer"><span>${b('من الفهم إلى المسؤولية','FROM UNDERSTANDING TO RESPONSIBILITY')}</span><span>AE / UK / FR / US</span></div></div></section><div class="metrics"><div class="metric"><b>20</b><span>${b('الحد الأقصى للمشاركين','maximum fellows per cycle')}</span></div><div class="metric"><b>04</b><span>${b('دول في مسار واحد','countries in one journey')}</span></div><div class="metric"><b>08</b><span>${b('مجالات للجدارة القيادية','leadership competency domains')}</span></div><div class="metric"><b>12</b><span>${b('شهراً للمتابعة المقترحة','months of proposed follow-up')}</span></div></div><section class="section"><div class="section-heading"><div><div class="eyebrow">${b('لماذا سَمْت؟','WHY SAMT')}</div><h2>${b('نُعدّ القائد لفهم الصورة كاملة.','Preparing leaders to see the whole picture.')}</h2></div><p>${b('تتغير التقنية والصناعة والسياسات. يربط سَمْت التعلم بالممارسة وبخبرة من سبق، ليصبح القرار أكثر وعياً بالسياق والنتائج.','Technology, industry and policy are changing. SAMT connects learning, practice and accumulated experience to develop decisions grounded in context and consequences.')}</p></div><div class="grid3">${[
    ['01',b('خبرة تنتقل بين الأجيال','Experience across generations'),b('إرشاد من قيادات متمرسة، وتعلّم متبادل، وتحويل الخبرة الضمنية إلى معرفة قابلة للتطبيق.','Experienced mentors, reciprocal learning and the translation of tacit knowledge into practical understanding.')],
    ['02',b('منظومة تتصل أجزاؤها','An interconnected institution'),b('من الاستراتيجية والعمليات إلى الأفراد والقدرات والموارد والصناعة والحوكمة؛ فهم الترابط قبل اتخاذ القرار.','From strategy and operations to people, capabilities, resources, industry and governance: understanding relationships before deciding.')],
    ['03',b('تعلّم يتحول إلى أثر','Learning that reaches the workplace'),b('مشروع مؤسسي يبدأ أثناء البرنامج، بمالك منفعة وخط أساس وخطة تطبيق ومراجعات بعد العودة.','An institutional project developed during the programme, with a benefits owner, baseline, implementation plan and follow-up reviews.')]
  ].map(([n,h,p])=>`<article class="feature"><span class="index">${n} / SAMT</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></section><section class="section"><div class="section-heading"><div><div class="eyebrow">${b('من الترشيح إلى الأثر','FROM NOMINATION TO IMPACT')}</div><h2>${b('رحلة واحدة.<br>مسؤولية تتطور في كل مرحلة.','One journey.<br>Growing responsibility at every stage.')}</h2></div>${link('programme',b('اكتشف رحلة الإعداد','Discover the programme'),'text-link')}</div><div class="grid3">${[
    [b('قبل الانطلاق','Before departure'),b('اختيار بالأدلة','Evidence-led selection'),b('ترشيح مؤسسي، مراجعة أهلية، تقييم موضوعي، وقرار لجنة موثق.','Institutional nomination, eligibility review, structured assessment and a documented panel decision.')],
    [b('خلال 16 أسبوعاً','During 16 weeks'),b('ممارسة وتغذية راجعة','Practice and feedback'),b('محطات وطنية ودولية، تكليفات أسبوعية، مشروع أثر وتقييم متعدد المصادر.','National and international stations, weekly assignments, an impact project and multi-source assessment.')],
    [b('بعد العودة','After returning'),b('تطبيق ومتابعة','Application and follow-up'),b('خطة 90 يوماً، إرشاد مستمر، ومراجعات للأداء والمنافع على مدى عام.','A 90-day plan, continuing mentorship and a year of performance and benefits reviews.')]
  ].map(([n,h,p])=>`<article class="feature"><span class="index">${n}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></section><section class="ribbon"><div><h2>${b('اختبر المنظومة بنفسك.','Experience the complete journey.')}</h2><p>${b('رشّح مشاركاً افتراضياً، راجع أدلته، تابع تعلّمه، وسجّل تقييمه.','Nominate a fictional candidate, review their evidence, follow their learning and record an assessment.')}</p></div><div class="actions">${link('demo',b('الدخول إلى التجربة','Open the demonstration'),'btn light')}</div></section><section class="meaning"><div class="meaning-word" lang="ar">سَمْت</div><div><span class="tag">${b('اسم يحمل وجهة ومعنى','A NAME WITH DIRECTION AND MEANING')}</span><h3>${b('الاتجاه الذي تختاره. والأثر الذي تتركه.','The direction you choose. The contribution you make.')}</h3><p>${b('يرتبط السمت في العربية بالاتجاه والهيئة والوقار. تحمل المبادرة هذا المعنى إلى إعداد القائد: وضوح الوجهة، وحسن السلوك، ووعي المسؤولية.','Samt in Arabic carries meanings of direction, bearing and dignified conduct. The initiative connects that meaning to leadership: clarity of purpose, sound conduct and responsibility.')}</p></div></section></div></main>`;}
  function programme(id){const s=D.stations.find(s=>s.id===id)||D.stations[0];return `<main id="main" tabindex="-1"><div class="shell"><div class="page-head"><span class="tag">${b('تصميم البرنامج المقترح','PROPOSED PROGRAMME DESIGN')}</span><h1>${b('أربع بيئات. فهم متكامل.','Four environments. An integrated perspective.')}</h1><p>${b('16 أسبوعاً متتالياً بدوام كامل. كل محطة تجيب عن سؤال قيادي وتنتج دليلاً عملياً. التوزيع التفصيلي مرجعي ويخضع لاتفاقات المضيفين.','16 consecutive full-time weeks. Each station addresses a leadership question and produces practical evidence. The detailed allocation is a reference design subject to host agreements.')}</p></div><div class="station-tabs" aria-label="${b('محطات البرنامج','Programme stations')}">${D.stations.map(x=>`<button class="station-tab" data-station="${x.id}" aria-pressed="${s.id===x.id}"><small class="mono">${String(x.start).padStart(2,'0')}—${String(x.end).padStart(2,'0')} / ${x.code}</small><strong>${tr(x.country)}</strong><small>${num(x.weeks)} ${b('أسابيع','weeks')}</small></button>`).join('')}</div><section class="station-detail" id="station-detail" aria-live="polite"><div><span class="tag">${tr(s.city)}</span><h2>${tr(s.title)}</h2><p>${tr(s.description)}</p><div class="pill-list">${s.hosts.map(h=>`<span class="pill">${tr(h)}</span>`).join('')}</div><p class="fine">${tr(s.note)}</p><div class="output"><strong>${b('مخرج المحطة','Station output')}</strong><p>${tr(s.output)}</p></div></div><div class="week-list">${D.weeks.slice(s.start-1,s.end).map(([h,p],i)=>`<article class="week-row"><b>${String(s.start+i).padStart(2,'0')}</b><div><h3>${tr(h)}</h3><p>${tr(p)}</p></div></article>`).join('')}</div></section><p class="help">${b('جميع الجهات ثابتة كمقترحات في التصميم، وليست شراكات معلنة أو مقاعد مؤكدة. تدمج أيام السفر والمراجعات في جدول الأسابيع الستة عشر.','All hosts remain proposed design anchors, not announced partnerships or confirmed seats. Travel and review days must fit within the 16-week timetable.')}</p><section class="section"><div class="section-heading"><div><div class="eyebrow">${b('إطار الجدارات','COMPETENCY FRAMEWORK')}</div><h2>${b('ما الذي نريد أن يتغير؟','What should change?')}</h2></div><p>${b('ثمانية مجالات مترابطة، لكل منها دليل أداء. الأوزان مقترحة للمعايرة خلال التجربة؛ لا تمنح الدرجة أهلية تلقائية للقيادة.','Eight connected domains, each supported by performance evidence. Weights are proposed for pilot calibration; a score does not automatically qualify someone for command.')}</p></div><div class="domain-grid">${D.domains.map((d,i)=>`<article class="domain"><span class="weight">0${i+1} / ${d.weight}%</span><h3>${tr(d.name)}</h3><p>${tr(d.description)}</p><details><summary>${b('دليل الأداء','Performance evidence')}</summary><p>${tr(d.evidence)}</p></details></article>`).join('')}</div><div class="followup"><h3>${b('بعد البرنامج: عام من التطبيق والإرشاد','After the programme: a year of application and mentoring')}</h3><p>${b('ثماني نقاط إرشاد مقترحة، مع مراجعات للأثر في الأيام 90 و180 و365. يظل المدير المباشر ومالك المنفعة طرفين في التحقق من التقدم.','Eight proposed mentoring touchpoints, with impact reviews at 90, 180 and 365 days. The line manager and benefits owner remain involved in validating progress.')}</p><div class="months">${[1,2,3,4,6,8,10,12].map(m=>`<span title="${b('الشهر','Month')} ${m}">${m}</span>`).join('')}</div></div></section></div></main>`;}
  const table=rows=>`<div class="table-wrap"><table><thead><tr>${rows[0].map(c=>`<th scope="col">${tr(c)}</th>`).join('')}</tr></thead><tbody>${rows.slice(1).map(r=>`<tr>${r.map(c=>`<td>${tr(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  function calculator(){return `<form class="calculator" id="budget-form"><h3>${b('حاسبة سيناريو التكلفة','Cost scenario calculator')}</h3><p class="fine">${b('مدخلات افتراضية لتوضيح طريقة الحساب، وليست عروض أسعار أو ميزانية مقترحة للاعتماد. الإقامة والمعيشة محسوبتان على 91 يوماً خارج الدولة. أضف تكاليف الإحلال والضرائب والتأمين والدعم عند إعداد الحالة الفعلية.','Illustrative inputs explain the calculation; these are not quotations or a budget submitted for approval. Accommodation and subsistence assume 91 days abroad. Add cover, taxes, insurance and support when preparing the actual case.')}</p><div class="field-grid">${[
    ['n',b('عدد المشاركين — حتى 20','Participants — up to 20'),10,20],['fee',b('رسوم التدريب لكل مشارك — درهم','Training fee per person — AED'),45000,1000000],['lodging',b('الإقامة لليوم خارج الدولة — درهم','Accommodation per day abroad — AED'),900,10000],['daily',b('المعيشة لليوم خارج الدولة — درهم','Subsistence per day abroad — AED'),350,10000],['travel',b('السفر لكل مشارك — درهم','Travel per person — AED'),18000,1000000],['fixed',b('تكاليف ثابتة للدورة — درهم','Fixed cycle cost — AED'),180000,10000000],['contingency',b('الاحتياطي %','Contingency %'),15,100]
  ].map(([id,name,value,max])=>`<div class="field"><label for="budget-${id}">${name}</label><input type="number" id="budget-${id}" name="${id}" min="${id==='n'?1:0}" max="${max}" step="${id==='n'?1:'any'}" value="${value}" required inputmode="decimal"></div>`).join('')}</div><div class="calc-result"><span>${b('إجمالي السيناريو الافتراضي','Illustrative scenario total')}</span><b id="budget-total" aria-live="polite" class="mono"></b></div><p id="budget-details" class="fine"></p><p id="budget-error" class="error" role="alert"></p></form>`;}
  function proposal(){return `<main id="main" tabindex="-1"><div class="shell"><div class="page-head"><span class="tag">${b('مقترح للاعتماد والتبني المؤسسي','PROPOSAL FOR INSTITUTIONAL ENDORSEMENT')}</span><h1>${b('ملف القرار. من القصد إلى التنفيذ.','The case for SAMT. From intent to delivery.')}</h1><p>${b('طلب تبنٍ مبدئي وتكليف بدراسة الجدوى والتصميم التنفيذي، يليه قرار مستقل لإطلاق دورة تجريبية.','A request for in-principle endorsement and commissioned feasibility and delivery design, followed by a separate pilot-launch decision.')}</p><div class="download-row"><a class="btn" href="docs/SAMT_Approval_Proposal.docx" download>${b('تحميل المقترح الكامل','Download full proposal')} <span aria-hidden="true">↓</span></a><button class="btn secondary" data-action="print">${b('طباعة هذه النسخة','Print this version')}</button></div><p class="fine">${b('المقترح الكامل بالعربية والإنجليزية • الإصدار 1.0 • 25 سبتمبر 2026','Full Arabic and English proposal • Version 1.0 • 25 September 2026')}</p></div><div class="proposal-layout"><nav class="toc" aria-label="${b('محتويات المقترح','Proposal contents')}">${D.proposal.map((p,i)=>`<a href="#proposal" data-scroll="p-${p.id}">${String(i+1).padStart(2,'0')} · ${tr(p.title)}</a>`).join('')}<a href="#proposal" data-scroll="references">${b('المراجع','References')}</a></nav><article>${D.proposal.map(p=>`<section class="proposal-section" id="p-${p.id}"><h2>${tr(p.title)}</h2>${p.paragraphs?p.paragraphs.map(x=>`<p>${tr(x)}</p>`).join(''):table(p.rows)}${p.id==='cost'?calculator():''}</section>`).join('')}<section class="proposal-section" id="references"><h2>${b('المراجع وحدود الاستدلال','References and limits of evidence')}</h2><p>${b('تسند هذه المصادر عناصر التصميم أو الاختصاص المعلن للجهات. لا تثبت اعتماد سمت أو استضافة مشاركيه. راجعت الروابط في 25 سبتمبر 2026.','These sources support elements of the design or the institutions’ stated remit. They do not establish SAMT approval or hosting arrangements. Links reviewed on 25 September 2026.')}</p><div class="source-list">${D.sources.map(s=>`<div class="source"><a href="${s.url}" target="_blank" rel="noopener"><span class="mono">[${s.id}]</span> ${tr(s.title)} ↗</a><small>${s.publisher}</small><p>${tr(s.use)}</p></div>`).join('')}</div></section></article></div></div></main>`;}
  const demoPages=[['overview','◫',['نظرة عامة','Overview']],['nomination','＋',['الترشيحات','Nominations']],['selection','▤',['الاختيار','Selection']],['learning','▥',['التعلم','Learning']],['monitoring','◷',['المتابعة','Monitoring']],['assessment','▦',['التقييم','Assessment']]];
  function fellowSelect(){return `<label class="sr-only" for="fellow-select">${b('اختر المشارك الافتراضي','Select fictional fellow')}</label><select id="fellow-select" aria-label="${b('اختر المشارك الافتراضي','Select fictional fellow')}">${state.fellows.map(f=>`<option value="${f.id}" ${f.id===activeFellow?'selected':''}>${b('المشارك الافتراضي','Sample fellow')} ${f.id}</option>`).join('')}</select>`;}
  const currentFellow=()=>state.fellows.find(f=>f.id===activeFellow)||state.fellows[0];
  function workspaceHead(title,sub,actions=''){return `<div class="workspace-head"><div><div class="eyebrow">${b('الدفعة التجريبية 01 • بيانات افتراضية','DEMO COHORT 01 • FICTIONAL DATA')}</div><h1>${title}</h1><p>${sub}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;}
  function demo(page='overview'){if(!demoPages.some(x=>x[0]===page))page='overview';const title=demoPages.find(x=>x[0]===page);return `<div class="notice"><span>${b('عرض تجريبي فقط. البيانات افتراضية والتغييرات تحفظ في هذا المتصفح؛ لا تُرسل ترشيحات إلى الوزارة.','Demonstration only. Data is fictional and changes stay in this browser; no nominations are sent to MOD.')}${!storageOK?' '+b('الحفظ المحلي غير متاح حالياً.','Browser storage is currently unavailable.'):''}</span><a href="#proposal" data-scroll="p-digital">${b('نطاق العرض','Demo scope')}</a></div><div class="demo-layout"><aside class="sidebar"><div class="sidebar-sticky"><div class="sidebar-title">${b('إدارة رحلة المشارك','THE FELLOW JOURNEY')}</div>${demoPages.map(([id,icon,n])=>`<a class="side-link ${id===page?'active':''}" href="#demo/${id}" ${id===page?'aria-current="page"':''}><span class="ico" aria-hidden="true">${icon}</span>${b(...n)}</a>`).join('')}<div class="sidebar-foot">${b('بيئة العرض','REVIEW ENVIRONMENT')}<strong>${b('وزارة الدفاع · مقترح','Ministry of Defence · Proposal')}</strong><p>${b('لا توجد حسابات فعلية أو صلاحيات مؤسسية في هذا العرض.','No real accounts or institutional access controls are present in this demo.')}</p></div></div></aside><main id="main" class="workspace" tabindex="-1">${({overview:overviewView,nomination:nominationView,selection:selectionView,learning:learningView,monitoring:monitoringView,assessment:assessmentView})[page]()}</main></div>`;}
  function overviewView(){const completed=state.fellows.reduce((a,f)=>a+f.completed.length,0),avg=Math.round(completed/(state.fellows.length*16||1)*100);return `${workspaceHead(b('رحلة القيادة، أمامك.','The leadership journey, at a glance.'),b('تابع حركة المشاركين والأدلة والإجراءات المطلوبة في الدفعة الافتراضية.','Follow participants, evidence and next actions in the fictional cohort.'),`<button class="btn small secondary" data-action="export">${b('تصدير بيانات العرض','Export demo data')}</button><button class="btn small secondary" data-action="reset">${b('إعادة الضبط','Reset demo')}</button>`)}<div class="stats-grid">${[
    [b('الترشيحات','Nominations'),state.candidates.length,b('سجلات افتراضية','fictional records')],
    [b('المشاركون المختارون','Selected fellows'),`${state.fellows.length}/${state.capacity}`,b('الحد الأعلى 20','maximum capacity 20')],
    [b('اكتمال أدلة التعلم','Learning evidence'),`${avg}%`,`${num(completed)} / ${num(state.fellows.length*16)} ${b('مهمة أسبوعية','weekly assignments')}`],
    [b('قيد مراجعة اللجنة','Awaiting the panel'),state.candidates.filter(c=>c.stage==='panel').length,b('قرارات بشرية موثقة','documented human decisions')]
  ].map(([h,v,s])=>`<div class="stat-card"><label>${h}</label><b class="mono">${v}</b><small>${s}</small></div>`).join('')}</div><div class="welcome-grid"><section class="panel"><div class="panel-heading"><h2>${b('حركة الترشيحات','Nomination pipeline')}</h2><a href="#demo/selection">${b('فتح قائمة الاختيار','Open selection')}</a></div><div class="funnel">${C.stages.map(s=>{const n=state.candidates.filter(c=>c.stage===s).length;return `<div class="funnel-row"><span>${lab(s)}</span><div class="track"><span style="width:${n/state.candidates.length*100}%"></span></div><span class="mono">${n}</span></div>`;}).join('')}</div></section><section class="panel"><div class="panel-heading"><h2>${b('ابدأ جولة المراجعة','Begin the review journey')}</h2></div>${[
    ['01','nomination',b('أنشئ ترشيحاً افتراضياً','Create a sample nomination'),b('اختر المسار والوظيفة ثم تحقق من الأهلية.','Choose a track and function, then check eligibility.')],
    ['02','selection',b('راجع الأدلة وسجّل القرار','Review evidence and record a decision'),b('قيّم الحالة وأضف رأي المقيم الثاني وسبب القرار.','Assess the case, confirm a second assessor and record the rationale.')],
    ['03','learning',b('أكمل مهمة تعلم','Complete a learning assignment'),b('افتح أسبوعاً وأضف تأملاً وشاهد أداء.','Open a week and add reflection and performance evidence.')],
    ['04','assessment',b('حدّث التقييم والمتابعة','Update assessment and follow-up'),b('راجع التقدم وحدد الإجراء التطويري التالي.','Review progress and identify the next development action.')]
  ].map(([n,p,h,s])=>`<a href="#demo/${p}" class="timeline-item"><span class="num">${n}</span><div><h3>${h}</h3><p>${s}</p></div></a>`).join('')}</section></div><section class="panel"><div class="panel-heading"><h2>${b('موجز المشاركين','Fellow snapshot')}</h2><a href="#demo/monitoring">${b('فتح المتابعة','Open monitoring')}</a></div>${fellowTable()}</section><section class="panel"><div class="panel-heading"><h2>${b('سجل أنشطة العرض','Demo activity record')}</h2><span class="fine">${b('سجل محلي غير محصّن للتدقيق','Local record, not a tamper-proof audit log')}</span></div><div class="audit-list">${state.audit.slice(0,6).map(a=>`<div class="audit-item"><span>${lab(a.type)} · <bdi class="mono">${esc(a.id)}</bdi></span><small>${esc(new Date(a.at).toLocaleString(lang==='ar'?'ar-AE':'en-GB'))}</small></div>`).join('')}</div></section>`;}
  function fellowTable(){return `<div class="table-wrap"><table><thead><tr><th scope="col">${b('المشارك الافتراضي','Sample fellow')}</th><th scope="col">${b('المسار','Track')}</th><th scope="col">${b('أدلة الأسابيع','Weekly evidence')}</th><th scope="col">${b('مشروع الأثر','Impact project')}</th><th scope="col">${b('متابعة الإرشاد','Mentor follow-up')}</th></tr></thead><tbody>${state.fellows.map(f=>{const c=state.candidates.find(c=>c.id===f.id);return `<tr><td><span class="mono">${f.id}</span></td><td>${lab(c.kind)}</td><td><span class="mono">${f.completed.length}/16</span><div class="track"><span style="width:${f.completed.length/16*100}%"></span></div></td><td>${stageBadge(f.project)}</td><td><span class="mono">${f.mentor.length}/8</span></td></tr>`;}).join('')}</tbody></table></div>`;}
  function nominationView(){return `${workspaceHead(b('الترشيحات','Nominations'),b('ترشيح مؤسسي يربط الإمكانات بالأهلية والأدلة.','Institutional nomination connecting potential, eligibility and evidence.'),`<button class="btn small" data-action="nominate">＋ ${b('ترشيح افتراضي جديد','New sample nomination')}</button>`)}<div class="toolbar"><label class="sr-only" for="candidate-search">${b('بحث بالمعرف','Search by ID')}</label><input id="candidate-search" type="search" placeholder="${b('ابحث بالمعرّف مثل D-001','Search an ID such as D-001')}" autocomplete="off"><label class="sr-only" for="kind-filter">${b('المسار','Track')}</label><select id="kind-filter"><option value="">${b('المساران','Both tracks')}</option><option value="military">${lab('military')}</option><option value="civilian">${lab('civilian')}</option></select><label class="sr-only" for="stage-filter">${b('المرحلة','Stage')}</label><select id="stage-filter"><option value="">${b('جميع المراحل','All stages')}</option>${C.stages.map(s=>`<option value="${s}">${lab(s)}</option>`).join('')}</select></div><div id="candidate-results">${candidateTable(state.candidates)}</div><p class="help">${b('تستخدم هذه التجربة معرّفات وأدواراً افتراضية؛ لا تدخل أسماء أو معرفات أو وثائق حقيقية.','This demonstration uses fictional IDs and roles; do not enter real names, identifiers or documents.')}</p>`;}
  function candidateTable(candidates){if(!candidates.length)return `<div class="panel empty">${b('لا توجد نتائج تطابق المرشحات. غيّر البحث أو المرشح.','No records match. Change the search or filters.')}</div>`;return `<div class="table-wrap"><table><thead><tr>${[b('المعرّف الافتراضي','Fictional ID'),b('المسار والخبرة','Track and career'),b('المجال','Function'),b('الحالة','Status'),b('المراجعة','Review')].map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${candidates.map(c=>`<tr><td><strong class="mono">${c.id}</strong></td><td>${lab(c.kind)}<br><span class="fine">${lab(c.career)}</span></td><td>${lab(c.function)}</td><td>${stageBadge(c.stage)}</td><td><button class="btn small secondary" data-candidate="${c.id}">${b('فتح الملف','Open record')}</button></td></tr>`).join('')}</tbody></table></div>`;}
  function selectionView(){return `${workspaceHead(b('الاختيار بالأدلة','Evidence-led selection'),b('الأوزان مقترحة. قرار اللجنة وتبريره يظلان أساس الاختيار.','Weights are proposed. The panel’s decision and rationale remain the basis for selection.'))}<div class="panel"><div class="toolbar"><label for="capacity">${b('سعة الدفعة','Cohort capacity')}</label><input id="capacity" type="number" min="${state.fellows.length||1}" max="20" value="${state.capacity}" style="max-width:95px;flex:0"><button class="btn small secondary" data-action="capacity">${b('حفظ','Save')}</button><span class="fine">${b('المختارون حالياً','Currently selected')}: <bdi class="mono">${state.fellows.length}/${state.capacity}</bdi></span></div><p class="fine">${b('تقييم كل معيار من 1 إلى 5، ثم يحول المجموع الموزون إلى 100. لا يوجد حد نجاح آلي. يسبق قرار الاختيار تحقق الأهلية ومراجعة المقيم الثاني والإحالة إلى اللجنة.','Each criterion is rated 1–5, then the weighted result is expressed out of 100. There is no automatic pass threshold. Eligibility, second-assessor review and panel referral precede selection.')}</p></div><div class="table-wrap"><table><thead><tr><th scope="col">${b('المعرّف','ID')}</th><th scope="col">${b('المسار','Track')}</th><th scope="col">${b('المرحلة','Stage')}</th><th scope="col">${b('النتيجة المساندة','Supporting score')}</th><th scope="col">${b('المقيم الثاني','Second assessor')}</th><th scope="col">${b('الإجراء','Action')}</th></tr></thead><tbody>${state.candidates.map(c=>`<tr><td class="mono">${c.id}</td><td>${lab(c.kind)}</td><td>${stageBadge(c.stage)}</td><td><span class="score">${C.weighted(c.scores)}</span><span class="fine"> / 100</span></td><td>${c.secondAssessor?b('تمت المراجعة','Reviewed'):b('مطلوبة','Required')}</td><td><button class="btn small secondary" data-candidate="${c.id}">${b('مراجعة الحالة','Review case')}</button></td></tr>`).join('')}</tbody></table></div>`;}
  function learningView(){const f=currentFellow();return `${workspaceHead(b('التعلم والممارسة','Learning and practice'),b('كل أسبوع مخرج. وكل مخرج فرصة لتطوير الحكم القيادي.','An output every week. A chance to develop leadership judgement with every output.'))}<div class="toolbar">${fellowSelect()}<span class="fine">${b('الأدلة المكتملة','Completed evidence')}: <bdi class="mono">${f.completed.length}/16</bdi></span></div><div class="panel"><div class="panel-heading"><h2>${b('مسارك عبر الأسابيع الستة عشر','Your 16-week journey')}</h2><span class="mono">${Math.round(f.completed.length/16*100)}%</span></div><div class="track red"><span style="width:${f.completed.length/16*100}%"></span></div><p class="help">${b('اختر أسبوعاً لإضافة التأمل ودليل الأداء. الإكمال في هذا العرض يعبّر عن تسجيل دليل افتراضي فقط.','Choose a week to add reflection and evidence. Completion here means only that sample evidence has been recorded.')}</p></div><div class="learning-grid">${D.weeks.map(([h,p],i)=>{const week=i+1,s=D.stations.find(s=>week>=s.start&&week<=s.end),done=f.completed.includes(week);return `<button class="learning-card ${done?'done':''}" data-week="${week}" aria-label="${b('الأسبوع','Week')} ${week}: ${tr(h)}${done?' — '+b('مكتمل','complete'):''}"><div class="week-number">${String(week).padStart(2,'0')}<span class="completion">${done?'✓':''}</span></div><h3>${tr(h)}</h3><small>${tr(s.country)}</small></button>`;}).join('')}</div>`;}
  function monitoringView(){const f=currentFellow();return `${workspaceHead(b('المتابعة ومشروع الأثر','Monitoring and the impact project'),b('يمتد التطوير إلى العمل الفعلي، بإرشاد منتظم ومسؤولية واضحة عن المنفعة.','Development continues into the workplace, with regular mentoring and clear benefits ownership.'))}<div class="toolbar">${fellowSelect()}</div><div class="grid2"><section class="panel"><div class="panel-heading"><h2>${b('ثماني نقاط إرشاد خلال 12 شهراً','Eight mentoring touchpoints over 12 months')}</h2><span class="mono">${f.mentor.length}/8</span></div><p class="fine">${b('اختر الأشهر التي تمت مراجعتها في السيناريو الافتراضي ثم احفظ ملاحظة المتابعة.','Select the months reviewed in the sample scenario, then save the follow-up note.')}</p><form id="monitoring-form"><div class="mentor-checks">${[1,2,3,4,6,8,10,12].map(m=>`<label><input type="checkbox" name="month" value="${m}" ${f.mentor.includes(m)?'checked':''}>${b('شهر','Month')} ${m}</label>`).join('')}</div><div class="field"><label for="project-stage">${b('حالة مشروع الأثر','Impact-project status')}</label><select id="project-stage" name="project">${['planned','progress','validated'].map(s=>`<option value="${s}" ${f.project===s?'selected':''}>${lab(s)}</option>`).join('')}</select></div><div class="field"><label for="project-note">${b('ملاحظة المتابعة والدليل','Follow-up note and evidence')}</label><textarea id="project-note" name="note" required minlength="12" maxlength="1500" placeholder="${b('استخدم مثالاً افتراضياً: الملاحظة، الدليل، الإجراء التالي والمالك.','Use a fictional example: observation, evidence, next action and owner.')}">${esc(f.projectNote)}</textarea></div><p class="error" id="monitor-error" role="alert"></p><button class="btn small" type="submit">${b('حفظ المتابعة','Save follow-up')}</button></form></section><section class="panel"><div class="panel-heading"><h2>${b('مراجعات تطبيق الأثر','Impact application reviews')}</h2></div>${[
    ['30',b('الاتفاق على خطة التطبيق','Agree the application plan'),b('اعتماد التحدي وخط الأساس ومالك المنفعة والوقت المخصص.','Confirm the challenge, baseline, benefits owner and allocated time.')],
    ['90',b('أول دليل من بيئة العمل','First workplace evidence'),b('مراجعة مخرج مطبق وملاحظات المدير؛ معالجة العوائق.','Review an applied output and manager feedback; address barriers.')],
    ['180',b('اختبار الاستدامة','Test sustainability'),b('مقارنة النتيجة بخط الأساس والتحقق من تفسير التغير.','Compare results with the baseline and examine explanations for change.')],
    ['365',b('مراجعة المنفعة والتوسع','Review benefits and scale'),b('توثيق القيمة والدروس وقرار الاستمرار أو التعديل.','Document value, lessons and the continue-or-adapt decision.')]
  ].map(([n,h,p])=>`<div class="timeline-item"><span class="num">${n}</span><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}<p class="help">${b('الأرقام بالأيام بعد العودة. النتائج المعروضة افتراضية ولا تثبت أثراً حقيقياً للبرنامج.','Numbers are days after return. Displayed results are fictional and do not establish actual programme impact.')}</p></section></div><section class="panel"><div class="panel-heading"><h2>${b('مقارنة ملفات المشاركين','Compare fellow records')}</h2></div>${fellowTable()}</section>`;}
  function assessmentView(){const f=currentFellow(),weighted=C.weighted(f.current,C.competencyWeights);return `${workspaceHead(b('تقييم النمو القيادي','Assess leadership development'),b('مقارنة بخط الأساس، مدعومة بأدلة وتفسير مهني.','A comparison with baseline, supported by evidence and professional interpretation.'))}<div class="toolbar">${fellowSelect()}</div><div class="grid2"><section class="panel"><div class="assessment-total"><b id="assessment-score">${weighted}</b><div><strong>${b('مؤشر وصفي من 100','Descriptive index out of 100')}</strong><p>${b('أوزان مقترحة • لا يمنح شهادة أو أهلية للقيادة','Proposed weights • Does not confer certification or command eligibility')}</p></div></div><form id="assessment-form"><div class="scale-grid">${D.domains.map((d,i)=>`<div class="scale-row"><label for="competency-${i}">${tr(d.name)}<small>${b('الوزن','Weight')}: ${d.weight}% · ${b('خط الأساس','Baseline')}: ${f.baseline[i]}/5</small></label><output for="competency-${i}" id="out-${i}">${f.current[i]}</output><input id="competency-${i}" name="score-${i}" type="range" min="1" max="5" step="1" value="${f.current[i]}"></div>`).join('')}</div><p class="help">${b('1 فهم أساسي · 2 تطبيق بإرشاد · 3 تطبيق في سياق مألوف · 4 تطبيق مستقل · 5 تبرير البدائل ونقل التعلم.','1 Basic understanding · 2 Guided application · 3 Application in familiar settings · 4 Independent application · 5 Reasoned alternatives and learning transfer.')}</p><div class="field"><label for="assessment-note">${b('دليل التقييم والإجراء التطويري','Assessment evidence and development action')}</label><textarea id="assessment-note" name="note" minlength="12" maxlength="1500" required>${esc(f.assessmentNote)}</textarea></div><p class="error" id="assessment-error" role="alert"></p><button class="btn small" type="submit">${b('حفظ التقييم','Save assessment')}</button></form></section><section class="panel"><div class="panel-heading"><h2>${b('خط الأساس والتقييم المحفوظ','Baseline and saved assessment')}</h2></div><div class="legend"><span><i class="baseline"></i>${b('خط الأساس','Baseline')}</span><span><i></i>${b('التقييم المحفوظ','Saved rating')}</span></div>${D.domains.map((d,i)=>`<div class="comparison-row"><span>${tr(d.name)}</span><div class="comparison-bars"><div class="base"><span style="width:${f.baseline[i]*20}%"></span></div><div><span style="width:${f.current[i]*20}%"></span></div></div><span class="mono">${f.current[i]}/5</span></div>`).join('')}<p class="help">${b('الفروق وصفية على سلم ترتيبي. لا تستنتج منها أثراً سببياً أو جاهزية فعلية دون مراجعة الأدلة والأداء في العمل.','Differences are descriptive on an ordinal scale. They do not establish causation or actual readiness without evidence review and workplace performance.')}</p><div class="output"><strong>${b('اكتمال ملف الأدلة','Evidence record completeness')}</strong><p>${b('مهام أسبوعية','Weekly assignments')}: <bdi class="mono">${f.completed.length}/16</bdi><br>${b('نقاط إرشاد','Mentoring touchpoints')}: <bdi class="mono">${f.mentor.length}/8</bdi><br>${b('ملاحظة تقييم مسجلة','Recorded assessment note')}: ${f.assessmentSaved?b('نعم','Yes'):b('لم تسجل بعد','Not yet recorded')}</p></div></section></div>`;}
  function nominationModal(){modal(b('ترشيح افتراضي جديد','New sample nomination'),`<p>${b('سيُنشأ معرف افتراضي تلقائياً. استخدم هذه الشاشة لاختبار مسار الترشيح دون بيانات أشخاص حقيقيين.','A fictional ID will be generated automatically. Use this screen to test nomination without real personal information.')}</p><form id="nomination-form"><div class="field-grid"><div class="field"><label for="nom-kind">${b('المسار','Track')}</label><select id="nom-kind" name="kind"><option value="military">${lab('military')}</option><option value="civilian">${lab('civilian')}</option></select></div><div class="field"><label for="nom-career">${b('المرحلة المهنية','Career stage')}</label><select id="nom-career" name="career"><option value="early">${lab('early')}</option><option value="mid">${lab('mid')}</option></select></div></div><div class="field"><label for="nom-function">${b('المجال الوظيفي','Professional function')}</label><select id="nom-function" name="function">${C.functions.map(f=>`<option value="${f}">${lab(f)}</option>`).join('')}</select></div><div class="checks"><label class="check"><input name="mod" type="checkbox" required><span>${b('يمثل السجل الافتراضي منتسباً لوزارة الدفاع.','The fictional record represents a MOD member.')}</span></label><label class="check"><input name="release" type="checkbox"><span>${b('التفرغ 16 أسبوعاً متتالياً مؤكد في هذا المثال.','Release for 16 consecutive weeks is confirmed in this scenario.')}</span></label><label class="check"><input name="evidence" type="checkbox"><span>${b('أدلة الأداء والدافع متاحة في هذا المثال.','Performance and motivation evidence is available in this scenario.')}</span></label></div><p id="nomination-error" class="error" role="alert"></p><div class="dialog-actions"><button class="btn" type="submit">${b('إضافة إلى الترشيحات','Add to nominations')}</button><button class="btn secondary" type="button" data-close>${b('إلغاء','Cancel')}</button></div></form>`);}
  function candidateModal(id){const c=state.candidates.find(x=>x.id===id);if(!c)return;const editable=C.transitions[c.stage].length>0;const criteria=[b('التحليل والتقدير','Analysis and judgement'),b('التعلم وفهم المنظومة','Learning and systems understanding'),b('قيادة الفريق','Team leadership'),b('الدافع والوعي الذاتي','Motivation and self-awareness'),b('التواصل','Communication')];modal(`${b('ملف افتراضي','Fictional record')} <bdi class="mono">${id}</bdi>`,`${stageBadge(c.stage)}<p style="margin-top:12px">${lab(c.kind)} · ${lab(c.career)} · ${lab(c.function)}</p><form id="candidate-form" data-id="${id}"><div class="checks">${[['mod',b('منتسب لوزارة الدفاع','MOD member')],['release',b('متاح للتفرغ الكامل','Available for full-time release')],['evidence',b('أدلة الأداء والدافع متاحة','Performance and motivation evidence available')]].map(([k,t])=>`<label class="check"><input type="checkbox" name="${k}" ${c.eligibility[k]?'checked':''} ${editable?'':'disabled'}><span>${t}</span></label>`).join('')}</div><p class="fine">${b('تقديرات افتراضية من 1 إلى 5؛ الأوزان مقترحة.','Fictional 1–5 ratings; weights are proposed.')}</p>${criteria.map((s,i)=>`<div class="score-input"><label for="selection-${i}">${s} · ${C.selectionWeights[i]}%</label><select id="selection-${i}" name="score-${i}" ${editable?'':'disabled'}>${[1,2,3,4,5].map(n=>`<option value="${n}" ${c.scores[i]===n?'selected':''}>${n}</option>`).join('')}</select></div>`).join('')}<div class="checks"><label class="check"><input type="checkbox" name="second" ${c.secondAssessor?'checked':''} ${editable?'':'disabled'}><span>${b('اكتملت مراجعة المقيم الثاني في المثال.','A second assessor’s review is complete in this example.')}</span></label></div>${editable?`<div class="field"><label for="candidate-target">${b('القرار المقترح في العرض','Demonstration decision')}</label><select id="candidate-target" name="target"><option value="${c.stage}">${b('حفظ المراجعة دون تغيير المرحلة','Save review without changing stage')}</option>${C.transitions[c.stage].map(s=>`<option value="${s}">${lab(s)}</option>`).join('')}</select></div><div class="field"><label for="candidate-reason">${b('سبب القرار أو ملاحظة المراجعة','Decision reason or review note')}</label><textarea id="candidate-reason" name="reason" required minlength="8" maxlength="1000" placeholder="${b('اكتب تفسيراً افتراضياً يستند إلى الأدلة.','Write a fictional evidence-based rationale.')}"></textarea></div><p id="candidate-error" class="error" role="alert"></p><div class="dialog-actions"><button class="btn" type="submit">${b('حفظ المراجعة والقرار','Save review and decision')}</button><button class="btn secondary" type="button" data-close>${b('إغلاق','Close')}</button></div>`:`<p class="help">${b('أغلق قرار الاختيار هذا السجل. يتابع المختارون رحلة التعلم والتقييم من صفحاتهم.','This selection decision has closed the record. Selected fellows continue through the learning and assessment pages.')}</p>`}</form>${c.notes.length?`<div class="output"><strong>${b('الملاحظات المسجلة','Recorded notes')}</strong>${c.notes.map(n=>`<p>${esc(n.text)}</p>`).join('')}</div>`:''}`);}
  function weekModal(week){const f=currentFellow(),item=D.weeks[week-1];const note=f.reflections[week]|| (f.completed.includes(week)?b('دليل افتراضي: مراجعة حالة مؤسسية وتحديد القرار والافتراضات وفرصة التحسين.','Sample evidence: reviewed an institutional case, identified the decision, assumptions and an improvement opportunity.'):'');modal(`${b('الأسبوع','Week')} ${week} · ${tr(item[0])}`,`<p>${tr(item[1])}</p><form id="week-form" data-week="${week}"><div class="field"><label for="week-note">${b('التأمل ودليل الأداء','Reflection and performance evidence')}</label><textarea id="week-note" name="note" minlength="12" maxlength="1500" required>${esc(tr(note))}</textarea></div><label class="check"><input type="checkbox" name="done" ${f.completed.includes(week)?'checked':''}><span>${b('تم تسجيل دليل المهمة الأسبوعية في هذا المثال.','Evidence for this weekly assignment is recorded in this example.')}</span></label><p id="week-error" class="error" role="alert"></p><div class="dialog-actions"><button class="btn" type="submit">${b('حفظ المهمة','Save assignment')}</button><button class="btn secondary" type="button" data-close>${b('إغلاق','Close')}</button></div></form>`);}
  function updateBudget(){const form=$('#budget-form');if(!form)return;const values=Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,v.trim()===''?NaN:Number(v)]));try{if(!form.checkValidity())throw new Error('invalid_budget');const r=C.budget(values);$('#budget-total').textContent=`${num(r.total)} ${b('د.إ','AED')}`;$('#budget-details').textContent=b(`قبل الاحتياطي: ${num(r.base)} درهم. الاحتياطي: ${num(r.contingency)} درهم.`,`Before contingency: AED ${num(r.base)}. Contingency: AED ${num(r.contingency)}.`);$('#budget-error').textContent='';}catch(e){$('#budget-total').textContent='—';$('#budget-details').textContent='';$('#budget-error').textContent=errorText(e.message);}}
  function updateAssessment(){const form=$('#assessment-form');if(!form)return;const scores=Array.from({length:8},(_,i)=>{const v=Number(form.elements[`score-${i}`].value);$(`#out-${i}`).textContent=v;return v;});$('#assessment-score').textContent=C.weighted(scores,C.competencyWeights);}
  function filterCandidates(){const search=$('#candidate-search')?.value.trim().toLowerCase()||'',kind=$('#kind-filter')?.value||'',stage=$('#stage-filter')?.value||'';if($('#candidate-results'))$('#candidate-results').innerHTML=candidateTable(state.candidates.filter(c=>(!search||c.id.toLowerCase().includes(search))&&(!kind||c.kind===kind)&&(!stage||c.stage===stage)));}
  function captureForms(){return [...document.forms].filter(f=>f.id!=='candidate-form').map(f=>({id:f.id,fields:[...f.elements].filter(e=>e.name).map(e=>({name:e.name,value:e.value,checked:e.checked,type:e.type}))}));}
  function restoreForms(forms){forms.forEach(f=>{const form=document.getElementById(f.id);if(!form)return;f.fields.forEach(d=>{[...form.elements].filter(el=>el.name===d.name).forEach(el=>{if(el.type==='checkbox'){if(el.value===d.value)el.checked=d.checked;}else el.value=d.value;});});});updateBudget();updateAssessment();}
  function render({scroll=false}={}){let [page='home',sub]=route();if(!D.nav.some(x=>x[0]===page))page='home';document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.title=`${b('سَمْت','SAMT')} | ${tr(D.nav.find(x=>x[0]===page)[1])}`;$('#app').innerHTML=header(page)+(page==='home'?home():page==='programme'?programme(sub):page==='proposal'?proposal():demo(sub))+footer();updateBudget();if(scroll){window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}}
  document.addEventListener('click',event=>{
    const target=event.target.closest('[data-action],[data-close],[data-station],[data-candidate],button[data-week],[data-scroll]');if(!target)return;
    if(target.hasAttribute('data-close')){closeModal();return;}
    if(target.dataset.scroll){event.preventDefault();const id=target.dataset.scroll;if(route()[0]!=='proposal'){location.hash='proposal';requestAnimationFrame(()=>requestAnimationFrame(()=>document.getElementById(id)?.scrollIntoView()));}else document.getElementById(id)?.scrollIntoView();return;}
    if(target.dataset.station){location.hash=`programme/${target.dataset.station}`;return;}
    if(target.dataset.candidate){candidateModal(target.dataset.candidate);return;}
    if(target.dataset.week){weekModal(Number(target.dataset.week));return;}
    switch(target.dataset.action){
      case 'language':{const drafts=captureForms();lang=lang==='ar'?'en':'ar';try{localStorage.setItem('samt6-language',lang);}catch{}render();restoreForms(drafts);break;}
      case 'menu':{const open=$('#navigation').classList.toggle('open');target.setAttribute('aria-expanded',open);break;}
      case 'nominate':nominationModal();break;
      case 'capacity':try{C.setCapacity(state,Number($('#capacity').value));persist();render();toast(b('تم تحديث سعة الدفعة.','Cohort capacity updated.'));}catch(e){toast(errorText(e.message));}break;
      case 'reset':modal(b('إعادة ضبط العرض؟','Reset the demonstration?'),`<p>${b('ستحذف التغييرات الافتراضية المحفوظة في هذا المتصفح وتستعاد بيانات البداية. يمكنك تصدير البيانات أولاً من لوحة النظرة العامة.','This removes fictional changes saved in this browser and restores the starting data. You can export first from the overview.')}</p><div class="dialog-actions"><button class="btn" data-action="confirm-reset">${b('إعادة ضبط البيانات الافتراضية','Reset fictional data')}</button><button class="btn secondary" data-close>${b('إلغاء','Cancel')}</button></div>`);break;
      case 'confirm-reset':state=C.seed();activeFellow='D-001';persist();closeModal();render();toast(b('استعيدت بيانات العرض.','Starting demo data restored.'));break;
      case 'export':{const payload={notice:'Fictional SAMT demonstration data. Not MOD records. Local browser activity is not a tamper-proof audit.',exported:new Date().toISOString(),...state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='SAMT_Fictional_Demo_Export.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(b('تم تصدير نسخة من البيانات الافتراضية.','A copy of the fictional data was exported.'));break;}
      case 'print':window.print();break;
    }
  });
  document.addEventListener('input',event=>{if(event.target.closest('#budget-form'))updateBudget();if(event.target.closest('#assessment-form')&&event.target.type==='range')updateAssessment();if(event.target.id==='candidate-search')filterCandidates();});
  document.addEventListener('change',event=>{if(['kind-filter','stage-filter'].includes(event.target.id))filterCandidates();if(event.target.id==='fellow-select'){activeFellow=event.target.value;render();}});
  document.addEventListener('submit',event=>{
    const form=event.target;if(!['nomination-form','candidate-form','week-form','monitoring-form','assessment-form','budget-form'].includes(form.id))return;event.preventDefault();const fd=new FormData(form);let err;
    try{
      if(form.id==='nomination-form'){err='nomination-error';const id=C.nominate(state,{kind:fd.get('kind'),career:fd.get('career'),function:fd.get('function'),eligibility:{mod:fd.has('mod'),release:fd.has('release'),evidence:fd.has('evidence')}});persist();closeModal();render();toast(`${b('أضيف الترشيح الافتراضي','Sample nomination added')} ${id}`);}
      if(form.id==='candidate-form'){err='candidate-error';const next=C.clone(state),c=next.candidates.find(c=>c.id===form.dataset.id);c.eligibility={mod:fd.has('mod'),release:fd.has('release'),evidence:fd.has('evidence')};c.scores=Array.from({length:5},(_,i)=>Number(fd.get(`score-${i}`)));c.secondAssessor=fd.has('second');const reason=String(fd.get('reason')||'');if(reason.trim().length<8)throw new Error('reason_required');if(fd.get('target')!==c.stage)C.transition(next,c.id,fd.get('target'),reason);else {C.weighted(c.scores);c.notes.push({at:new Date().toISOString(),text:reason.trim()});C.record(next,'decision',c.id);}state=next;persist();closeModal();render();toast(b('حفظت المراجعة والقرار الافتراضي.','Sample review and decision saved.'));}
      if(form.id==='week-form'){err='week-error';C.saveWeek(state,currentFellow().id,Number(form.dataset.week),fd.get('note'),fd.has('done'));persist();closeModal();render();toast(b('حفظ دليل التعلم.','Learning evidence saved.'));}
      if(form.id==='monitoring-form'){err='monitor-error';const note=String(fd.get('note')||'').trim();if(note.length<12)throw new Error('evidence_required');const f=currentFellow();f.mentor=fd.getAll('month').map(Number);f.project=fd.get('project');f.projectNote=note;C.record(state,'monitoring',f.id);persist();render();toast(b('حفظت المتابعة.','Follow-up saved.'));}
      if(form.id==='assessment-form'){err='assessment-error';C.saveAssessment(state,currentFellow().id,Array.from({length:8},(_,i)=>Number(fd.get(`score-${i}`))),fd.get('note'));persist();render();toast(b('حفظ التقييم.','Assessment saved.'));}
      if(form.id==='budget-form')updateBudget();
    }catch(e){const error=err?document.getElementById(err):null;if(error){error.textContent=errorText(e.message);error.scrollIntoView({block:'nearest'});}else toast(errorText(e.message));}
  });
  window.addEventListener('hashchange',()=>{if($('#modal').open)closeModal();render({scroll:true});});
  $('#modal').addEventListener('cancel',()=>lastFocus?.focus());
  $('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
  render();
})();
